import { PlaneGeometry, Group, Mesh } from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new Group();
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  // Build plane geometry matching atlas region aspect (512x320 ≈ 1.6:1)
  const aspect = 512 / 320;
  const planeWidth = 1.6;
  const planeHeight = planeWidth / aspect;
  const geometry = new PlaneGeometry(planeWidth, planeHeight);

  // Material with texture offset for atlas region
  const material = new MeshBasicNodeMaterial({ transparent: true });

  // Load texture and apply atlas region UV offset
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      tex.wrapS = tex.wrapT = 1000; // RepeatWrapping
      tex.repeat.set(512 / tex.image.width, 320 / tex.image.height);
      tex.offset.set(0, 1 - (320 / tex.image.height));
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // Render text if present
  if (items.length > 0) {
    const headlineItem = items.find(i => i.role === 'headline' || i.text === 'Features');
    if (headlineItem) {
      const text = ctx.fontAtlas.createText(headlineItem.text, {
        fontSize: headlineItem.typography?.fontSize || 96,
        color: '#e8ecf2',
        align: 'center',
        letterSpacingPx: 0.02 * (headlineItem.typography?.fontSize || 96)
      });
      text.position.set(0, 0.1, 0.01);
      text.scale.set(0.004, 0.004, 0.004);
      group.add(text);
    }
  }

  // Static composition - no animations or interactivity per spec

  // Event handlers (none for static node)
  group.userData.handlers = {};

  // Cleanup
  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (material.map) material.map.dispose();
  };

  return group;
}
